INSERT INTO `sliders` VALUES (3,'Online course (Full Stack Web Developer)','លោកអ្នកអាចចុះឈ្មោះចូលសិក្សាក្នុងពេលឆាប់ៗនេះ ទំនាក់ទំនងទូរស័ព្ទលេង ០៩៨ ២០៥ ៤៩៩ / ០៩៩ ២០៥ ៤៩៩','image/slider/1819561197164064.jpg','2024-11-30 06:25:09','2025-01-12 17:40:04',NULL),(4,'សេវាកម្មថតចម្រៀងបែបស្តង់ដា និងទទួលផលិតវីដេអូ','នៅទីនេះយើងនឹងផ្តល់ជូនលោកអ្នកនូវគុណភាពយ៉ាងល្អឥតខ្ចោះក្រោយពេលលោកអ្នកប្រើប្រាស់ សេវាកម្មផលិតចម្រៀង និងថត MV','image/slider/1819856214174767.jpg','2024-11-30 06:25:51','2024-12-30 09:17:48',NULL),(5,'សេវាកម្មបង្កើតវែបសាយ និងប្រព័ន្ធគ្រប់គ្រងទិន្នន័យ','បង្កើតវែបសាយដើម្បីផ្សព្វផ្សាយ និងគ្រប់គ្រងប្រព័ន្ធ សម្រាប់ហាង និងអាជីវកម្មរបស់លោកអ្នក','image/slider/1818982756992267.jpeg','2024-12-09 03:45:24','2024-12-20 17:52:17',NULL);
